INSERT INTO "customers" ("id", "name", "email", "avatar_url", "role", "bio", "badges", "preferences", "points", "joined_at", "updated_at") VALUES
  ('u-demo', 'Demo User', 'demo@ngetag.id', 'https://picsum.photos/seed/demo-user/200/200', 'customer', 'Penjelajah kafe aesthetic dan event live music di Jakarta.', '[{"id":"b-community-jakarta","label":"Komunitas Jakarta","category":"community"},{"id":"b-interest-coffee","label":"Coffee Enthusiast","category":"interest"},{"id":"b-activity-reviewer","label":"Aktif Review","category":"activity"},{"id":"b-explorer-local","label":"Local Explorer","category":"explorer"},{"id":"b-contributor-early","label":"Early Contributor","category":"contributor"}]'::jsonb, '{"favoriteTagIds":["t1","t3","t8"],"city":"Jakarta"}'::jsonb, 1240, '2025-01-15T08:00:00.000Z', NULL),
  ('u1', 'Andini Wijaya', 'u1@ngetag.mock', 'https://picsum.photos/seed/u-andini/100/100', 'customer', 'Content writer yang hobi hunting kafe dan pameran foto di Jakarta Selatan.', '[{"id":"b-community-jakarta","label":"Komunitas Jakarta","category":"community"},{"id":"b-interest-coffee","label":"Coffee Enthusiast","category":"interest"},{"id":"b-contributor-early","label":"Early Contributor","category":"contributor"}]'::jsonb, '{"favoriteTagIds":["t1","t8","t9"],"city":"Jakarta"}'::jsonb, 860, '2026-05-08T13:14:00.000Z', NULL),
  ('u2', 'Reza Pratama', 'u2@ngetag.mock', 'https://picsum.photos/seed/u-reza/100/100', 'customer', 'Pecinta live music dan Valorant ranked. Weekend selalu ada agenda konser.', '[{"id":"b-interest-music","label":"Music Lover","category":"interest"},{"id":"b-interest-gaming","label":"Gamer","category":"interest"},{"id":"b-activity-reviewer","label":"Aktif Review","category":"activity"}]'::jsonb, '{"favoriteTagIds":["t3","t18","t20"],"city":"Jakarta"}'::jsonb, 640, '2026-04-29T13:14:00.000Z', NULL),
  ('u3', 'Dewi Lestari', 'u3@ngetag.mock', 'https://picsum.photos/seed/u-dewi/100/100', 'customer', 'Remote worker yang butuh Wi-Fi cepat, colokan, dan kopi enak.', '[{"id":"b-interest-coffee","label":"Coffee Enthusiast","category":"interest"},{"id":"b-explorer-local","label":"Local Explorer","category":"explorer"}]'::jsonb, '{"favoriteTagIds":["t1","t15","t16"],"city":"Jakarta"}'::jsonb, 415, '2026-05-13T13:14:00.000Z', NULL),
  ('u4', 'Bagas Saputra', 'u4@ngetag.mock', 'https://picsum.photos/seed/u-bagas/100/100', 'customer', 'Runner pemula, rutin ikut Sunday long run bareng Runcrew Jakarta.', '[{"id":"b-community-runcrew","label":"Runcrew Jakarta","category":"community"},{"id":"b-activity-checkin","label":"Rajin Check-in","category":"activity"}]'::jsonb, '{"favoriteTagIds":["t11","t14"],"city":"Jakarta"}'::jsonb, 300, '2026-04-28T13:14:00.000Z', NULL),
  ('u5', 'Citra Maharani', 'u5@ngetag.mock', 'https://picsum.photos/seed/u-citra/100/100', 'customer', 'Fotografer amatir yang percaya lighting terbaik ada di jam emas.', '[{"id":"b-interest-photo","label":"Photo Hunter","category":"interest"},{"id":"b-activity-reviewer","label":"Aktif Review","category":"activity"},{"id":"b-contributor-verified","label":"Verified Reviewer","category":"contributor"}]'::jsonb, '{"favoriteTagIds":["t8","t7","t9"],"city":"Jakarta"}'::jsonb, 980, '2026-05-11T13:14:00.000Z', NULL),
  ('u6', 'Faisal Hakim', 'u6@ngetag.mock', 'https://picsum.photos/seed/u-faisal/100/100', 'customer', 'Founder early-stage, sering pindah coworking dan demo night.', '[{"id":"b-interest-wfc","label":"Remote Worker","category":"interest"},{"id":"b-contributor-early","label":"Early Contributor","category":"contributor"}]'::jsonb, '{"favoriteTagIds":["t16","t12","t6"],"city":"Jakarta"}'::jsonb, 520, '2026-04-26T13:14:00.000Z', NULL),
  ('u7', 'Nadia Rahmadani', 'u7@ngetag.mock', 'https://picsum.photos/seed/u-nadia/100/100', 'customer', 'Fans Nada Senja. Suka akustik, vinyl, dan rooftop.', '[{"id":"b-community-nada-senja","label":"Nada Senja Fans","category":"community"},{"id":"b-activity-reviewer","label":"Aktif Review","category":"activity"}]'::jsonb, '{"favoriteTagIds":["t3","t8","t20"],"city":"Jakarta"}'::jsonb, 720, '2026-05-10T13:14:00.000Z', NULL),
  ('u8', 'Ilham Aditya', 'u8@ngetag.mock', 'https://picsum.photos/seed/u-ilham/100/100', 'customer', 'Gamer yang juga mengikuti kabar startup. Sering mampir kafe 24 jam.', '[{"id":"b-interest-gaming","label":"Gamer","category":"interest"}]'::jsonb, '{"favoriteTagIds":["t18","t20"],"city":"Jakarta"}'::jsonb, 260, '2026-05-01T13:14:00.000Z', NULL),
  ('u-admin-curator', 'Admin Kurasi NgeTag', 'admin@ngetag.id', 'https://picsum.photos/seed/u-admin-curator/200/200', 'admin', 'Admin kurasi konten: spot, event, promo, dan review tag.', '[{"id":"b-contributor-verified","label":"Verified Reviewer","category":"contributor"},{"id":"b-contributor-early","label":"Early Contributor","category":"contributor"},{"id":"b-activity-reviewer","label":"Aktif Review","category":"activity"}]'::jsonb, '{"favoriteTagIds":["t1","t2","t3","t8","t20"],"city":"Jakarta"}'::jsonb, 5000, '2024-06-01T03:00:00.000Z', '2026-09-30T09:15:00.000Z'),
  ('u-owner-kopi-tuku', 'Ayu Pramesti', 'owner.kopituku@ngetag.id', 'https://picsum.photos/seed/u-ayu/200/200', 'owner', 'Owner Kopi Tuku Cipete. Terbuka pada feedback jujur pelanggan.', '[{"id":"b-interest-coffee","label":"Coffee Enthusiast","category":"interest"},{"id":"b-contributor-early","label":"Early Contributor","category":"contributor"}]'::jsonb, '{"favoriteTagIds":["t1","t15","t16"],"city":"Jakarta"}'::jsonb, 1540, '2024-09-12T04:30:00.000Z', '2026-08-18T07:20:00.000Z'),
  ('u-owner-organizer-jfp', 'Rizky Ananda', 'organizer.jfp@ngetag.id', 'https://picsum.photos/seed/u-rizky/200/200', 'owner', 'Promoter musik indie. Mengelola listing event dan promo organizer.', '[{"id":"b-community-nada-senja","label":"Nada Senja Fans","category":"community"},{"id":"b-interest-music","label":"Music Lover","category":"interest"}]'::jsonb, '{"favoriteTagIds":["t3","t20"],"city":"Jakarta"}'::jsonb, 610, '2025-02-02T09:00:00.000Z', NULL),
  ('u-power-salsabila', 'Salsabila Putri', 'salsabila.putri@ngetag.id', 'https://picsum.photos/seed/u-salsabila/200/200', 'customer', 'Hampir semua kafe dan event Jakarta sudah dicoba. Rela antre demi review.', '[{"id":"b-community-jakarta","label":"Komunitas Jakarta","category":"community"},{"id":"b-interest-coffee","label":"Coffee Enthusiast","category":"interest"},{"id":"b-interest-music","label":"Music Lover","category":"interest"},{"id":"b-interest-photo","label":"Photo Hunter","category":"interest"},{"id":"b-activity-reviewer","label":"Aktif Review","category":"activity"},{"id":"b-activity-checkin","label":"Rajin Check-in","category":"activity"},{"id":"b-explorer-local","label":"Local Explorer","category":"explorer"},{"id":"b-explorer-rooftop","label":"Rooftop Hunter","category":"explorer"},{"id":"b-explorer-nightowl","label":"Night Owl","category":"explorer"},{"id":"b-contributor-verified","label":"Verified Reviewer","category":"contributor"}]'::jsonb, '{"favoriteTagIds":["t1","t2","t3","t4","t5","t6","t7","t8","t9","t10","t11","t12","t13","t14","t15","t16","t17","t18","t19","t20"],"city":"Jakarta Selatan"}'::jsonb, 4200, '2025-03-22T11:45:00.000Z', '2026-10-10T13:05:00.000Z'),
  ('u-new-rani', 'Rani Kusuma', 'rani.kusuma@ngetag.id', NULL, 'customer', NULL, '[]'::jsonb, NULL, 0, '2026-10-01T02:15:00.000Z', NULL),
  ('u-legacy-budi', 'Budi Santoso', 'budi.santoso@ngetag.id', 'https://picsum.photos/seed/u-budi/200/200', 'customer', NULL, '[{"id":"b-interest-coffee","label":"Coffee Enthusiast","category":"interest"}]'::jsonb, '{"favoriteTagIds":["t11"]}'::jsonb, 45, '2024-08-17T06:40:00.000Z', NULL),
  ('u-bandung-yoga', 'Yoga Pratama', 'yoga.pratama@ngetag.id', 'https://picsum.photos/seed/u-yoga/200/200', 'customer', 'Sering dinas ke Jakarta, tapi basis utama di Bandung.', '[{"id":"b-interest-photo","label":"Photo Hunter","category":"interest"}]'::jsonb, '{"favoriteTagIds":["t1","t8"],"city":"Bandung"}'::jsonb, 180, '2025-11-09T08:25:00.000Z', NULL)
